/** A nominal member slot. */
export type MemberSlot =
    /** Property keyed by a static key. */
    | {
          readonly kind: "key";
          readonly key: StaticKey;
      }
    /** Constructor role member. */
    | {
          readonly kind: "constructor";
      }
    /** New role member. */
    | {
          readonly kind: "new";
      }
    /** Callable role member. */
    | {
          readonly kind: "call";
      }
;

export const MemberSlot = {
    /** Property keyed by a static key. */
    key(key: StaticKey): MemberSlot {
        return { kind: "key", key };
    },

    /** Constructor role member. */
    "constructor"(): MemberSlot {
        return { kind: "constructor" };
    },

    /** New role member. */
    "new"(): MemberSlot {
        return { kind: "new" };
    },

    /** Callable role member. */
    call(): MemberSlot {
        return { kind: "call" };
    },

    /** Encode this value. */
    encode(writer: BinaryWriter, value: MemberSlot): void {
        encodeMemberSlot(writer, value);
    },

    /** Decode one MemberSlot. */
    decode(reader: BinaryReader): MemberSlot {
        return decodeMemberSlot(reader);
    },

    /** Return this value as JSON. */
    toJson(value: MemberSlot): Json {
        return toJsonMemberSlot(value);
    },

    /** Return one MemberSlot from one JSON value. */
    fromJson(value: Json): MemberSlot {
        return fromJsonMemberSlot(value);
    },
};

/** Encode one MemberSlot. */
export function encodeMemberSlot(writer: BinaryWriter, value: MemberSlot): void {
    switch (value.kind) {
        case "key":
            writer.writeUnsigned(0);
            encodeStaticKey(writer, value.key);
            return;
        case "constructor":
            writer.writeUnsigned(1);
            return;
        case "new":
            writer.writeUnsigned(2);
            return;
        case "call":
            writer.writeUnsigned(3);
            return;
    }

    throw new SerdeError("unknown enum variant");
}

/** Decode one MemberSlot. */
export function decodeMemberSlot(reader: BinaryReader): MemberSlot {
    const variant = reader.readNumber();

    switch (variant) {
        case 0: {
            const key = decodeStaticKey(reader);

            return { kind: "key", key };
        }
        case 1: {
            return { kind: "constructor" };
        }
        case 2: {
            return { kind: "new" };
        }
        case 3: {
            return { kind: "call" };
        }
    }

    throw new SerdeError(`unknown enum variant index: ${variant}`);
}

/** Return one JSON value for one MemberSlot. */
export function toJsonMemberSlot(value: MemberSlot): Json {
    switch (value.kind) {
        case "key":
            return {
                kind: "key",
                key: toJsonStaticKey(value.key),
            };
        case "constructor":
            return {
                kind: "constructor",
            };
        case "new":
            return {
                kind: "new",
            };
        case "call":
            return {
                kind: "call",
            };
    }

    throw new SerdeError("unknown enum variant");
}

/** Return one MemberSlot from one JSON value. */
export function fromJsonMemberSlot(value: Json): MemberSlot {
    const object = jsonObject(value);
    const kind = jsonString(jsonField(object, "kind"));

    switch (kind) {
        case "key":
            return {
                kind,
                key: fromJsonStaticKey(jsonField(object, "key")),
            };
        case "constructor":
            return {
                kind,
            };
        case "new":
            return {
                kind,
            };
        case "call":
            return {
                kind,
            };
    }

    throw new SerdeError(`unknown enum variant: ${kind}`);
}
